import{_ as n,l as o,o as e,c as r,v as t,p as s,x as i,d,i as _,S as m}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"下一词分类","description":"","frontmatter":{"title":"下一词分类","date":"2026-09-10T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/clm-as-next-token.md","filePath":"llm/clm-as-next-token.md","lastUpdated":1789023840000}'),p={name:"llm/clm-as-next-token.md"};function h(c,a,E,B,f,u){const l=o("Mermaid");return e(),r("div",null,[a[1]||(a[1]=t('<h1 id="下一词分类" tabindex="-1">下一词分类 <a class="header-anchor" href="#下一词分类" aria-label="Permalink to &quot;下一词分类&quot;">​</a></h1><div class="epigraph"><p>一段离散符号的联合概率可以因式分解成「每一次只猜下一个符号」；训练目标于是变成一串共享参数的分类。</p><footer>—— 据 Shannon, Prediction and Entropy of Printed English, Bell System Technical Journal, 1951；Bengio et al., A Neural Probabilistic Language Model, JMLR 2003 整理</footer></div><p><a href="/llm/logspace-underflow">对数空间与 underflow</a>规定似然只在对数里相加。本课不重写 logsumexp。缺口是：把这条原则用到符号序列上——每个位置一次对词表的分类，损失是各位置交叉熵之和。本课仍把符号当成已经编号的类别，不解释词表从哪来；那是深度学习基础结束之后，<a href="/llm/token-as-discrete-unit">离散符号与词表</a>的第一课。也不把网络结构写成 Transformer。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>交叉熵课处理的是单次分类：一个 \\(z\\in\\mathbb{R}^{K}\\)，一个标签 \\(y\\)。语言是变长序列 \\(t_{1:n}\\)。若把整句当成一个类别，类别数随长度指数增长，无法参数化。若把各位置当成独立分类，又丢掉「前面决定后面」的条件结构。缺口是链式法则给出的因式分解</p> \\[P(t_{1:n})=\\prod_{i=1}^{n}P(t_i\\mid t_{\\lt i}), \\]<p>每一项都是在大小为 \\(K\\) 的词表上的一次分类，\\(K\\) 与 \\(n\\) 无关。对数似然是 \\(\\sum_i\\log P(t_i\\mid t_{\\lt i})\\)，恰好是上一课的求和。</p><p>「下一词」是训练时的监督接口，不是对人类阅读过程的断言。条件可以来自左侧上下文、来自双向编码器的其它位置，或来自编码器输出；本课取自回归默认：位置 \\(i\\) 的标签是 \\(t_i\\)，输入是 \\(t_{\\lt i}\\)（实现上常喂 \\(t_{1:n}\\) 再把标签左移一位）。双向与掩码语言模型是后课变体，不在这里展开。</p><h3 id="下一词不是整句回归" tabindex="-1">下一词不是整句回归 <a class="header-anchor" href="#下一词不是整句回归" aria-label="Permalink to &quot;下一词不是整句回归&quot;">​</a></h3><p>把句子嵌入成一个向量再回归到另一个向量，损失无法告诉模型「第 \\(i\\) 个符号错了」。分类头必须在每个位置上给出 \\(|V|\\) 维 logits。句向量可以作检索，不能代替本课的目标。同样，逐字符的均方误差把符号当成连续值，编号的算术没有意义——那是嵌入课才纠正的事，本课先要求损失定义在离散类别上。</p><p><span class="marginnote">实现里常见形状：logits \\((B,n,|V|)\\)，标签 \\((B,n)\\)，在最后一轴做交叉熵，再对非填充位置求平均。填充位置必须掩掉，否则 PAD 会主导平均损失。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>参数共享：同一个网络 \\(f\\) 在每个位置产出 \\(z_i=f(t_{\\lt i})\\in\\mathbb{R}^{|V|}\\)，再走稳定 softmax。训练损失</p> \\[L=-\\frac{1}{\\sum_i m_i}\\sum_i m_i\\log p_i[t_i], \\]<p>\\(m_i\\) 是有效位置掩码。教师信号是语料里真实的 \\(t_i\\)，不是模型自己上一步的抽样——后课 seq2seq 会把这一点命名为 teacher forcing，本课只先用上「用真值当条件」。评估用平均负对数似然或 \\(\\mathrm{e}^{L}\\) 作为困惑度；比较模型时长度归一必须一致，按 token 还是按词、按字节要声明。</p>',15)),(e(),s(m,null,{default:i(()=>[_(l,{id:"mermaid-39",class:"mermaid",graph:"flowchart%20TD%0A%20%20CTX%5B%22%E4%B8%8A%E4%B8%8B%E6%96%87%20t%20%E5%B0%8F%E4%BA%8E%20i%22%5D%20--%3E%20NET%5B%22%E5%85%B1%E4%BA%AB%E5%8F%82%E6%95%B0%E7%9A%84%E7%BD%91%E7%BB%9C%22%5D%0A%20%20NET%20--%3E%20Z%5B%22%E4%BD%8D%E7%BD%AE%20i%20%E7%9A%84%20logits%22%5D%0A%20%20Z%20--%3E%20CE%5B%22%E4%B8%8E%E6%A0%87%E7%AD%BE%20t_i%20%E7%9A%84%E4%BA%A4%E5%8F%89%E7%86%B5%22%5D%0A%20%20CE%20--%3E%20SUM%5B%22%E5%AF%B9%E6%95%B0%E7%A9%BA%E9%97%B4%E6%B1%82%E5%92%8C%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>因式分解把「生成整句」变成「重复使用同一分类头」。参数量不随 \\(n\\) 增长，长度只增加计算次数。梯度是各位置 \\(p_i-e_{t_i}\\) 沿共享参数求和：高频下一词模式贡献大，罕见续写贡献小。这与嵌入行按频次更新是同一现象，只是现在监督落在分类头上。</p><p>自回归接口还规定了推理方式：必须按时间一步一步取下一个符号，不能并行出整句（训练时因 teacher forcing 可以并行算所有位置的损失，那是实现巧合，不是条件独立）。本课不讲解码算法；只需承认训练目标与推理过程用的是同一因式分解。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不定义词表、BPE、UNK，也不定义注意力。网络 \\(f\\) 可以是稍后的 RNN 或 Transformer，这里只要求它输出 \\(|V|\\) 维 logits。下一课起进入优化：<a href="/llm/sgd-learning-rate">梯度下降与学习率</a>假定已经有了可对参数求导的标量 \\(L\\)。后课默认：语言模型的训练损失是掩码后的平均下一词交叉熵。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>序列联合概率因式分解为下一词分类；对数似然是各位置交叉熵之和。</li><li>分类头宽度等于词表大小；形状 \\((B,n,|V|)\\) 对 \\((B,n)\\)。</li><li>填充位置必须从平均里去掉。</li><li>训练可用真值上下文并行算损失；推理仍按条件逐步展开。</li><li>出处：Shannon, 1951；Bengio et al., JMLR 2003。</li></ul>',7))])}const T=n(p,[["render",h]]);export{g as __pageData,T as default};
